 "content": "def transform(grid):
    """Change the background-colored tail after a solid left-aligned bar to 1."""
    out = [row[:] for row in grid]
    if not grid or not grid[0]:
        return out
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    for r, row in enumerate(grid):
        # A qualifying row is a uniform non-background prefix followed only by
        # background cells, with both sections present.
        k = 0
        while k < len(row) and row[k] != bg:
            k += 1
        if k == 0 or k == len(row):
            continue
        color = row[0]
        if all(v == color for v in row[:k]) and all(v == bg for v in row[k:]):
            out[r][k:] = [1] * (len(row) - k)
    return out


